function togglePause(){if(!game.running||game.dialog)return;game.paused=!game.paused;ui.pause.classList.toggle('hidden',!game.paused);}
function showDialogue(speaker,lines,tag=''){game.dialog=true;game.dialogQueue=lines;game.dialogIndex=0;game.dialogTag=tag;ui.speaker.textContent=speaker;ui.dialogue.classList.remove('hidden');typeLine(lines[0]);}
let typeTimer;function typeLine(text){clearInterval(typeTimer);ui.line.textContent='';let i=0;typeTimer=setInterval(()=>{ui.line.textContent=text.slice(0,++i);if(i>=text.length)clearInterval(typeTimer)},24)}
function advanceDialogue(){if(!game.dialog)return;const current=game.dialogQueue[game.dialogIndex];if(ui.line.textContent!==current){clearInterval(typeTimer);ui.line.textContent=current;return;}game.dialogIndex++;if(game.dialogIndex<game.dialogQueue.length){typeLine(game.dialogQueue[game.dialogIndex]);return;}game.dialog=false;ui.dialogue.classList.add('hidden');if(game.dialogTag==='intro'){showDialogue('Ember',['Ria… Lichtwahrerin. Hörst du mich?','Die Schattenweber haben die Sonne gestohlen. Drei Splitter halten ihre Welt zusammen.','Finde den Wächter. Bring den ersten Splitter heim.'],'quest');}else if(game.dialogTag==='boss'){showDialogue('Ember',['Der erste Splitter ist frei. Doch dies war nur ein Schatten.','Der Weg führt tiefer — durch Wald, Kristall und die versunkene Stadt.'],'bossdone');}else if(game.dialogTag==='final'){endingChoice();}}
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function updateHUD(){const pl=game.player;$('#healthFill').style.width=`${clamp(pl.hp,0,100)}%`;$('#energyFill').style.width=`${clamp(pl.energy,0,100)}%`;$('#region').textContent=['Der verlassene Wald','Die Kristallhöhlen','Die versunkene Stadt'][game.region];$('#objective').textContent=game.objective===0?'Finde den Kristall im Dorf':game.objective===1?'Besiege den Schattenweber':game.objective===2?'Erreiche den nächsten Lichtpfad':game.objective===3?'Finde die drei Sonnensplitter':'Folge Embers Ruf';if(game.boss?.alive){$('#bossbar').style.display='block';$('#bossFill').style.width=`${game.boss.hp/game.boss.max*100}%`;$('#bossname').textContent=game.boss.type}else $('#bossbar').style.display='none'}
function ensureAudio(){if(audio)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),gain=ctx.createGain();gain.gain.value=.055;gain.connect(ctx.destination);const osc=ctx.createOscillator(),filter=ctx.createBiquadFilter(),pad=ctx.createGain();osc.type='triangle';osc.frequency.value=55;filter.type='lowpass';filter.frequency.value=240;pad.gain.value=.34;osc.connect(filter);filter.connect(pad);pad.connect(gain);osc.start();const lfo=ctx.createOscillator(),lg=ctx.createGain();lfo.frequency.value=.13;lg.gain.value=12;lfo.connect(lg);lg.connect(osc.frequency);lfo.start();audio={ctx,gain,osc,pad};}catch(e){}}
function beep(freq=420,duration=.12,type='sine'){if(!audio)return;const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+duration);o.connect(g);g.connect(audio.gain);o.start();o.stop(audio.ctx.currentTime+duration)}
